INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4019289, 573722, 61818, '<td valign="top">Only good shot in the challenge.  Well, besides my own of course.</td>', 'Only good shot in the challenge.  Well, besides my own of course.', '2007-08-22 01:35:45.000000', NULL, 1),
(4019329, 573511, 82282, '<td valign="top">Looks very surreal.  Great shot.  I love the color.</td>', 'Looks very surreal.  Great shot.  I love the color.', '2007-08-22 01:45:31.000000', NULL, 1),
(4019338, 572914, 82282, '<td valign="top">Excellent concept but the background seems to take away the focus from the subject.</td>', 'Excellent concept but the background seems to take away the focus from the subject.', '2007-08-22 01:46:33.000000', NULL, 1),
(4019340, 574998, 82282, '<td valign="top">Shot could have been better if the horizon was straight.</td>', 'Shot could have been better if the horizon was straight.', '2007-08-22 01:47:34.000000', NULL, 1),
(4019347, 574753, 82282, '<td valign="top">Nice effect and choice of background.</td>', 'Nice effect and choice of background.', '2007-08-22 01:48:52.000000', NULL, 1),
(4019353, 574327, 82282, '<td valign="top">Excellent colors on the Church, but the power lines are very distracting.</td>', 'Excellent colors on the Church, but the power lines are very distracting.', '2007-08-22 01:50:20.000000', NULL, 1),
(4019365, 574660, 82282, '<td valign="top">Kind of a freaky place to think, but good shot nonetheless.</td>', 'Kind of a freaky place to think, but good shot nonetheless.', '2007-08-22 01:52:06.000000', NULL, 1),
(4019381, 575545, 52472, '<td valign="top">Impressive sky! The title does not work for me. In order to reach for heaven, a shot close to the church with a wide-angle would be far mor impressive. I would have cropped the building on the right.</td>', 'Impressive sky! The title does not work for me. In order to reach for heaven, a shot close to the church with a wide-angle would be far mor impressive. I would have cropped the building on the right.', '2007-08-22 01:59:10.000000', NULL, 1),
(4019409, 575505, 82282, '<td valign="top">This photo seems a bit too post processed and the tree in the front is quite distracting.  Try not to sharpen too much as it causes a lot of noise that takes away from the photo.</td>', 'This photo seems a bit too post processed and the tree in the front is quite distracting.  Try not to sharpen too much as it causes a lot of noise that takes away from the photo.', '2007-08-22 02:07:17.000000', NULL, 1),
(4019424, 572624, 82282, '<td valign="top">Great symmetry.  I''m assuming that it isn''t yours as the paper on the top left takes a bit away from this shot.</td>', 'Great symmetry.  I''m assuming that it isn''t yours as the paper on the top left takes a bit away from this shot.', '2007-08-22 02:12:30.000000', NULL, 1),
(4019428, 575298, 82282, '<td valign="top">Main subject seems out of focus.  It looks like you focused on the leaves close by.</td>', 'Main subject seems out of focus.  It looks like you focused on the leaves close by.', '2007-08-22 02:15:18.000000', NULL, 1),
(4019439, 575474, 82282, '<td valign="top">The windows seem to take away from the main subject.</td>', 'The windows seem to take away from the main subject.', '2007-08-22 02:21:14.000000', NULL, 1),
(4019453, 574329, 82282, '<td valign="top">Great concept and perspective.</td>', 'Great concept and perspective.', '2007-08-22 02:25:55.000000', NULL, 1),
(4019455, 572866, 82282, '<td valign="top">This photo must''ve taken your breath away when you took it.  I love it.</td>', 'This photo must''ve taken your breath away when you took it.  I love it.', '2007-08-22 02:26:31.000000', NULL, 1),
(4019456, 575454, 82282, '<td valign="top">Nicely done.</td>', 'Nicely done.', '2007-08-22 02:26:49.000000', NULL, 1),
(4019458, 573324, 82282, '<td valign="top">Good shot!  So which way did you go?  Left or right?  =)</td>', 'Good shot!  So which way did you go?  Left or right?  =)', '2007-08-22 02:27:27.000000', NULL, 1),
(4019461, 573842, 82282, '<td valign="top">The concept of dancing in the graveyard freaks me out, but I like the shot nonetheless.</td>', 'The concept of dancing in the graveyard freaks me out, but I like the shot nonetheless.', '2007-08-22 02:28:35.000000', NULL, 1),
(4019464, 572862, 82282, '<td valign="top">You gotta love those colors.  Beautifully executed!</td>', 'You gotta love those colors.  Beautifully executed!', '2007-08-22 02:29:30.000000', NULL, 1),
(4019521, 575212, 33446, '<td valign="top">Easy to look at - it''s kind and makes a viewer want to be there!</td>', 'Easy to look at - it''s kind and makes a viewer want to be there!', '2007-08-22 02:53:59.000000', NULL, 1),
(4019551, 573091, 39344, '<td valign="top">I enjoy the emotion of this shot - I think a narrower field of view could have emphasized the cross (the bible / necklace on the left could have been a little more out of focus)</td>', 'I enjoy the emotion of this shot - I think a narrower field of view could have emphasized the cross (the bible / necklace on the left could have been a little more out of focus)', '2007-08-22 03:10:00.000000', NULL, 1),
(4019553, 574985, 39344, '<td valign="top">I think this pic is too cluttered - if you had changed the angle or the field of vision, you could have emphasized the statue or the wall.</td>', 'I think this pic is too cluttered - if you had changed the angle or the field of vision, you could have emphasized the statue or the wall.', '2007-08-22 03:10:55.000000', NULL, 1),
(4019555, 575104, 39344, '<td valign="top">Good shot, although I think the angle could have been changed a little to make the V shape of the sky a little more off-centre.</td>', 'Good shot, although I think the angle could have been changed a little to make the V shape of the sky a little more off-centre.', '2007-08-22 03:11:48.000000', NULL, 1),
(4019558, 573881, 39344, '<td valign="top">I think changing the angle could have emphasized the "subject" of this photo - the Madonna. Perhaps taking the photo closer to her?</td>', 'I think changing the angle could have emphasized the "subject" of this photo - the Madonna. Perhaps taking the photo closer to her?', '2007-08-22 03:14:09.000000', NULL, 1),
(4019560, 575183, 39344, '<td valign="top">I think you could have tightened up the frame on the bible / glass and left out the bottom 1/3 of this photo. Otherwise great lighting.</td>', 'I think you could have tightened up the frame on the bible / glass and left out the bottom 1/3 of this photo. Otherwise great lighting.', '2007-08-22 03:15:43.000000', NULL, 1),
(4019568, 574432, 39344, '<td valign="top">I think this photo lacks a subject - it is a little too busy. Perhaps focusing on one tombstone could have been better?</td>', 'I think this photo lacks a subject - it is a little too busy. Perhaps focusing on one tombstone could have been better?', '2007-08-22 03:18:06.000000', NULL, 1),
(4019570, 575307, 39344, '<td valign="top">Good lighting - however, I think the foreground detracts a little in this pic.</td>', 'Good lighting - however, I think the foreground detracts a little in this pic.', '2007-08-22 03:19:06.000000', NULL, 1),
(4019575, 573723, 39344, '<td valign="top">A good composition - the only improvement I can recommend is a tighter field of vision to blur the chair / door a little.</td>', 'A good composition - the only improvement I can recommend is a tighter field of vision to blur the chair / door a little.', '2007-08-22 03:19:53.000000', NULL, 1),
(4019579, 575515, 80814, '<td valign="top">Sweet!  Is that an eye?</td>', 'Sweet!  Is that an eye?', '2007-08-22 03:20:46.000000', NULL, 1),
(4019580, 575472, 39344, '<td valign="top">Good shot (similar to my entry!) I think that a white background could have been better - the contrast between the certificate and the dark background is a bit harsh.</td>', 'Good shot (similar to my entry!) I think that a white background could have been better - the contrast between the certificate and the dark background is a bit harsh.', '2007-08-22 03:21:42.000000', NULL, 1),
(4019581, 575002, 80814, '<td valign="top">This is awesome.</td>', 'This is awesome.', '2007-08-22 03:21:45.000000', NULL, 1),
(4019589, 572814, 39344, '<td valign="top">I like the tight focus on the statue - however, the blade of grass (or whatever) that seems to "stick out of" the eyebrow of the statue is a distraction - I think you should have removed it and retaken the shot.</td>', 'I like the tight focus on the statue - however, the blade of grass (or whatever) that seems to "stick out of" the eyebrow of the statue is a distraction - I think you should have removed it and retaken the shot.', '2007-08-22 03:23:18.000000', NULL, 1),
(4019595, 574753, 39344, '<td valign="top">A good composition - the only thing I think would improve this pic is if the flagpole was exactly 90 degrees upright (it looks like it''s leaning a little to the right).</td>', 'A good composition - the only thing I think would improve this pic is if the flagpole was exactly 90 degrees upright (it looks like it''s leaning a little to the right).', '2007-08-22 03:24:24.000000', NULL, 1),
(4019599, 574769, 39344, '<td valign="top">This is a great composition - I think the lighting needs a little work. The bright patch of sky in the background distracts from the angel and the angel looks a little underexposed. Perhaps a fill-in flash or metering off the angel (and waiting till the sun had gone down a little more) could have helped.</td>', 'This is a great composition - I think the lighting needs a little work. The bright patch of sky in the background distracts from the angel and the angel looks a little underexposed. Perhaps a fill-in flash or metering off the angel (and waiting till the sun had gone down a little more) could have helped.', '2007-08-22 03:26:26.000000', NULL, 1),
(4019605, 572580, 39344, '<td valign="top">A different angle or field of view could have given this photo a definite subject (at the moment no single element stands out).</td>', 'A different angle or field of view could have given this photo a definite subject (at the moment no single element stands out).', '2007-08-22 03:28:11.000000', NULL, 1),
(4019610, 575180, 39344, '<td valign="top">I think the subject is too far away and the contrast too stark - you could have recomposed this or used fill in flash to get some detail in the foreground.</td>', 'I think the subject is too far away and the contrast too stark - you could have recomposed this or used fill in flash to get some detail in the foreground.', '2007-08-22 03:29:20.000000', NULL, 1),
(4019612, 574167, 39344, '<td valign="top">Good colouring - I think a dead-on angle to the statuette would have been better?</td>', 'Good colouring - I think a dead-on angle to the statuette would have been better?', '2007-08-22 03:30:37.000000', NULL, 1),
(4019618, 575505, 39344, '<td valign="top">I think the composition here is great - but the lighting is not. The sky is overexposed while the foreground is underexposed. A little less light in the sky or a ND-grad filter could have helped.</td>', 'I think the composition here is great - but the lighting is not. The sky is overexposed while the foreground is underexposed. A little less light in the sky or a ND-grad filter could have helped.', '2007-08-22 03:32:40.000000', NULL, 1),
(4019622, 572475, 39344, '<td valign="top">Excellent shot - great compisition, lighting and contrast.</td>', 'Excellent shot - great compisition, lighting and contrast.', '2007-08-22 03:33:15.000000', NULL, 1),
(4019627, 575412, 39344, '<td valign="top">You caught the lightning (a difficult enough feat) but the rest of the pic lets you down - it''s a bit monotonal and there seems to be nothing interesting to draw the eye. A different composition and other colours would have improved this shot.</td>', 'You caught the lightning (a difficult enough feat) but the rest of the pic lets you down - it''s a bit monotonal and there seems to be nothing interesting to draw the eye. A different composition and other colours would have improved this shot.', '2007-08-22 03:34:57.000000', NULL, 1),
(4019629, 573722, 39344, '<td valign="top">I think a tighter view of the hands (or more of the face) would have improved the composition of this pic. The lighting is great though.</td>', 'I think a tighter view of the hands (or more of the face) would have improved the composition of this pic. The lighting is great though.', '2007-08-22 03:35:58.000000', NULL, 1),
(4019632, 573318, 39344, '<td valign="top">An interesting contrast (the statues and the buildings) but I think you could have done more in the composition - perhaps tightened up on the angel or used a field of view that blurred the buildings slightly?</td>', 'An interesting contrast (the statues and the buildings) but I think you could have done more in the composition - perhaps tightened up on the angel or used a field of view that blurred the buildings slightly?', '2007-08-22 03:37:19.000000', NULL, 1),
(4019635, 573029, 39344, '<td valign="top">The horizontal line through the middle of this photo makes a potentially interesting shot a little flat. You also have "dead space" in the foreground (the grass in front of the tombstones). A change of angle would have helped.</td>', 'The horizontal line through the middle of this photo makes a potentially interesting shot a little flat. You also have "dead space" in the foreground (the grass in front of the tombstones). A change of angle would have helped.', '2007-08-22 03:38:44.000000', NULL, 1),
(4019638, 575130, 39344, '<td valign="top">Good composition and lighting - well done!</td>', 'Good composition and lighting - well done!', '2007-08-22 03:39:17.000000', NULL, 1),
(4019641, 572519, 39344, '<td valign="top">A different lighting could have emphasized the colour of the roses. You could also have tightened up a little on the roses (rather than have the bottom 1/3 of the pic dominated by a pole)</td>', 'A different lighting could have emphasized the colour of the roses. You could also have tightened up a little on the roses (rather than have the bottom 1/3 of the pic dominated by a pole)', '2007-08-22 03:41:01.000000', NULL, 1),
