(4022661, 574505, 10665, '<td valign="top">I would have cropped out the golf cart</td>', 'I would have cropped out the golf cart', '2007-08-22 22:32:44.000000', NULL, 1),
(4022663, 572610, 10665, '<td valign="top">Great framing by the tree</td>', 'Great framing by the tree', '2007-08-22 22:33:29.000000', NULL, 1),
(4022664, 575373, 81433, '<td valign="top">This is a good idea but I do not care of the reflection on the table or the crop.  I think the photographer could look for another angle and it would be much better. But it really is a great idea!</td>', 'This is a good idea but I do not care of the reflection on the table or the crop.  I think the photographer could look for another angle and it would be much better. But it really is a great idea!', '2007-08-22 22:33:47.000000', NULL, 1),
(4022670, 572850, 81433, '<td valign="top">This is a good idea, I like the idea of the flag being in color, but the rest of the picture needs to be softened a bit.  The grass and tree limbs are too "sharp".</td>', 'This is a good idea, I like the idea of the flag being in color, but the rest of the picture needs to be softened a bit.  The grass and tree limbs are too "sharp".', '2007-08-22 22:34:51.000000', NULL, 1),
(4022672, 574917, 41675, '<td valign="top">Pretty landscape. I like the color of the water.</td>', 'Pretty landscape. I like the color of the water.', '2007-08-22 22:37:46.000000', NULL, 1),
(4022675, 575130, 41675, '<td valign="top">Looks like an interesting structure. I wish it was a little closer to the back wall. I''m curious as to what the little jars are.</td>', 'Looks like an interesting structure. I wish it was a little closer to the back wall. I''m curious as to what the little jars are.', '2007-08-22 22:39:12.000000', NULL, 1),
(4022676, 573205, 81433, '<td valign="top">I really, really like this.  I love how the shadow of the cross is on the open Bible.  The words are clear enough to read, the lighting is good.  It''s just a really good picture!</td>', 'I really, really like this.  I love how the shadow of the cross is on the open Bible.  The words are clear enough to read, the lighting is good.  It''s just a really good picture!', '2007-08-22 22:39:24.000000', NULL, 1),
(4022682, 573324, 41675, '<td valign="top">I like the angle and the light. Very cool!</td>', 'I like the angle and the light. Very cool!', '2007-08-22 22:42:35.000000', NULL, 1),
(4022683, 575408, 81433, '<td valign="top">I like the sunset and cross idea.  It is very nice.   I do not like what looks like smog, haze or dust in the sky.  If that could be taken out, this shot would be much better.</td>', 'I like the sunset and cross idea.  It is very nice.   I do not like what looks like smog, haze or dust in the sky.  If that could be taken out, this shot would be much better.', '2007-08-22 22:42:41.000000', NULL, 1),
(4022686, 572914, 41675, '<td valign="top">The lighting is a little harsh, but I like your concept.</td>', 'The lighting is a little harsh, but I like your concept.', '2007-08-22 22:44:13.000000', NULL, 1),
(4022687, 575378, 81433, '<td valign="top">This is a good idea but the crop is not right, the color is off and it''s a bit soft.  Using a flash bounced off the ceiling or reflector may have made the shot better.  Good idea though.</td>', 'This is a good idea but the crop is not right, the color is off and it''s a bit soft.  Using a flash bounced off the ceiling or reflector may have made the shot better.  Good idea though.', '2007-08-22 22:44:14.000000', NULL, 1),
(4022692, 573318, 41675, '<td valign="top">I like the clarity and crispness of your image. A little busy at the very bottom with the different busts, but nice image.</td>', 'I like the clarity and crispness of your image. A little busy at the very bottom with the different busts, but nice image.', '2007-08-22 22:45:07.000000', NULL, 1),
(4022694, 572324, 10665, '<td valign="top">I love the unconventional composition, but the color is a bit distracting</td>', 'I love the unconventional composition, but the color is a bit distracting', '2007-08-22 22:45:17.000000', NULL, 1),
