(4022700, 575511, 81433, '<td valign="top">Good idea but it needs to be cropped differently, maybe square instead of rectangular and the words really need to be focused.</td>', 'Good idea but it needs to be cropped differently, maybe square instead of rectangular and the words really need to be focused.', '2007-08-22 22:46:40.000000', NULL, 1),
(4022705, 574764, 41675, '<td valign="top">Very nice lighting capture. I always find it interesting that a photo can fit a variety of challenges with the right title.</td>', 'Very nice lighting capture. I always find it interesting that a photo can fit a variety of challenges with the right title.', '2007-08-22 22:47:52.000000', NULL, 1),
