(4029549, 575276, 45377, '<td valign="top">I like the composition, nice angle. The light is a bit flat though.</td>', 'I like the composition, nice angle. The light is a bit flat though.', '2007-08-26 08:00:06.000000', NULL, 1),
(4029550, 575067, 23251, '<td valign="top">Now that''s nice!  Blown out in the glass window but you can''t have both in basic editing anyway.  Nice take on the challenge.</td>', 'Now that''s nice!  Blown out in the glass window but you can''t have both in basic editing anyway.  Nice take on the challenge.', '2007-08-26 08:00:57.000000', NULL, 1),
(4029551, 573722, 48471, '<td valign="top">I see, I mean I think that the person has a strong character, but I''m not sure about this, although tattoos and the dirty fingers tell me so, but anyhow, this makes the small cross bigger, because he''s standing behind it. Good.</td>', 'I see, I mean I think that the person has a strong character, but I''m not sure about this, although tattoos and the dirty fingers tell me so, but anyhow, this makes the small cross bigger, because he''s standing behind it. Good.', '2007-08-26 08:02:27.000000', NULL, 1),
(4029552, 575212, 48471, '<td valign="top">Ah, if only she (or is it he?) was contemplating, instead of having a walk and looking for something, as it looks to me. Still, a great geometry and a good find.</td>', 'Ah, if only she (or is it he?) was contemplating, instead of having a walk and looking for something, as it looks to me. Still, a great geometry and a good find.', '2007-08-26 08:03:54.000000', NULL, 1),
(4029553, 575505, 23251, '<td valign="top">Sorry I don''t really like the colours.  I find my eye''s drawn to the shaded underexposed Date palm with all the leading lines taking my eyes there.</td>', 'Sorry I don''t really like the colours.  I find my eye''s drawn to the shaded underexposed Date palm with all the leading lines taking my eyes there.', '2007-08-26 08:04:04.000000', NULL, 1),
(4029555, 573450, 48471, '<td valign="top">Pet bottle hurts this image. Since when water is identified by pet bottles? The idea is to be saluted, but not the realisation.</td>', 'Pet bottle hurts this image. Since when water is identified by pet bottles? The idea is to be saluted, but not the realisation.', '2007-08-26 08:05:58.000000', NULL, 1),
(4029557, 575067, 48471, '<td valign="top">You got me wondering who''s the guy in the photo?</td>', 'You got me wondering who''s the guy in the photo?', '2007-08-26 08:08:00.000000', NULL, 1),
(4029570, 575540, 48471, '<td valign="top">At this moment, while browsing and voting, Strauss'' Blue Danube is playing and Odyssey 2001 is in my mind, and then, this photo pops up. Good. You get a point plus for the luck.</td>', 'At this moment, while browsing and voting, Strauss'' Blue Danube is playing and Odyssey 2001 is in my mind, and then, this photo pops up. Good. You get a point plus for the luck.', '2007-08-26 08:14:59.000000', NULL, 1),
(4029572, 575394, 23251, '<td valign="top">The specks (Sensor dust?) can be healed or cloned out leagally and it would help to make the background clean.</td>', 'The specks (Sensor dust?) can be healed or cloned out leagally and it would help to make the background clean.', '2007-08-26 08:16:08.000000', NULL, 1),
(4029574, 575099, 48471, '<td valign="top">Time: (maybe) the only thing that changes, while nothing else changes. Devil has nothing to do with it. As for the photo, a good one.</td>', 'Time: (maybe) the only thing that changes, while nothing else changes. Devil has nothing to do with it. As for the photo, a good one.', '2007-08-26 08:16:55.000000', NULL, 1),
