(4029588, 573894, 23251, '<td valign="top">The lighting and people are great but unfortunatly they are out of focus.</td>', 'The lighting and people are great but unfortunatly they are out of focus.', '2007-08-26 08:33:28.000000', NULL, 1),
(4029590, 574486, 23251, '<td valign="top">it could do with some straightening, crop and rotate would do it..</td>', 'it could do with some straightening, crop and rotate would do it..', '2007-08-26 08:35:29.000000', NULL, 1),
(4029592, 575434, 23251, '<td valign="top">That''s nice, sharp as and not blown out at all on a very difficult shot! Also a nice take on the Challenge.  Good Luck!</td>', 'That''s nice, sharp as and not blown out at all on a very difficult shot! Also a nice take on the Challenge.  Good Luck!', '2007-08-26 08:38:56.000000', NULL, 1),
