(4035110, 573722, 49954, '<td valign="top">Don''t normally care for cross jewelry, but the contrast here is quite nice..  One of the tops this round.</td>', 'Don''t normally care for cross jewelry, but the contrast here is quite nice..  One of the tops this round.', '2007-08-28 10:15:50.000000', NULL, 1),
(4035112, 575141, 49954, '<td valign="top">Not the best "photo" in the bunch technically, but the moment capture is priceless.  One of my top picks.</td>', 'Not the best "photo" in the bunch technically, but the moment capture is priceless.  One of my top picks.', '2007-08-28 10:16:37.000000', NULL, 1),
(4035114, 573182, 49954, '<td valign="top">Nice contrast with the building and the sky.</td>', 'Nice contrast with the building and the sky.', '2007-08-28 10:17:12.000000', NULL, 1),
(4035170, 575194, 64176, '<td valign="top">That is so beautiful...</td>', 'That is so beautiful...', '2007-08-28 10:57:21.000000', NULL, 1),
(4035260, 575545, 24454, '<td valign="top">What a killer sunset!   Like a beautiful fire in the sky!</td>', 'What a killer sunset!   Like a beautiful fire in the sky!', '2007-08-28 11:47:08.000000', NULL, 1),
(4035263, 573384, 24454, '<td valign="top">Amen!!!!!!!!!!!!!!!!!!</td>', 'Amen!!!!!!!!!!!!!!!!!!', '2007-08-28 11:47:42.000000', NULL, 1),
(4035267, 574860, 24454, '<td valign="top">Perfect!!!!!!  I love how the pages look worn and "lived-in"</td>', 'Perfect!!!!!!  I love how the pages look worn and "lived-in"', '2007-08-28 11:48:47.000000', NULL, 1),
(4035269, 575434, 24454, '<td valign="top">This is nice.  Very well presented.  And yes, very sacred!</td>', 'This is nice.  Very well presented.  And yes, very sacred!', '2007-08-28 11:49:57.000000', NULL, 1);
