(4037199, 575002, 68504, '<td valign="top">Outstanding.  The foreground is totally enticing.</td>', 'Outstanding.  The foreground is totally enticing.', '2007-08-29 01:58:43.000000', NULL, 0),
(4037200, 573842, 57570, '<td valign="top">congrats on ur ribbon!!</td>', 'congrats on ur ribbon!!', '2007-08-29 01:59:17.000000', NULL, 0),
