(4037207, 573511, 14212, '<td valign="top">Well deserved blue! Beautiful shot.</td>', 'Well deserved blue! Beautiful shot.', '2007-08-29 02:00:31.000000', NULL, 0),
(4037234, 575531, 2389, '<td valign="top">Thanks for the sincere comments...<br/><br/><i>Message edited by author 2007-08-29 01:12:15.</i></td>', 'Thanks for the sincere comments...', '2007-08-29 02:05:21.000000', '2007-08-29 02:12:15.000000', 0),
(4037248, 573842, 33068, '<td valign="top">I recognized this place immediately from your "wing" entry. What a cool place to shoot and your work is fantastic.  Well done.</td>', 'I recognized this place immediately from your "wing" entry. What a cool place to shoot and your work is fantastic.  Well done.', '2007-08-29 02:08:18.000000', NULL, 0);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4037252, 574791, 68504, '<td valign="top">Like this the way it is, exposurewise, making it almost like an Escher drawing.  Original, creative.</td>', 'Like this the way it is, exposurewise, making it almost like an Escher drawing.  Original, creative.', '2007-08-29 02:09:54.000000', NULL, 0),
(4037254, 574764, 42013, '<td valign="top">Holy Smokes! You produce these with some regularity. Great timing and congrats!  8/your top 10! <br/><br/><i>Message edited by author 2007-08-29 01:12:10.</i></td>', 'Holy Smokes! You produce these with some regularity. Great timing and congrats!  8/your top 10! ', '2007-08-29 02:11:09.000000', '2007-08-29 02:12:10.000000', 0),
(4037264, 575412, 60862, '<td valign="top">Got a 6 from me, Julie.  I hope you''re happy with the shot.  I''ve never managed to capture lightning, so I think it''s pretty cool!</td>', 'Got a 6 from me, Julie.  I hope you''re happy with the shot.  I''ve never managed to capture lightning, so I think it''s pretty cool!', '2007-08-29 02:16:48.000000', NULL, 0),
(4037271, 573124, 60862, '<td valign="top">Congrats on the score, Deb - once again we''re neighbors! :)  My only nitpick was to think about cropping off some of the left side so the tower gets more out of the middle.  It''s kind of halfway out now, but that leaves composition uncomfortable to me.  I realize that''d make it an even taller photo.</td>', 'Congrats on the score, Deb - once again we''re neighbors! :)  My only nitpick was to think about cropping off some of the left side so the tower gets more out of the middle.  It''s kind of halfway out now, but that leaves composition uncomfortable to me.  I realize that''d make it an even taller photo.', '2007-08-29 02:19:02.000000', NULL, 0),
(4037280, 575141, 60862, '<td valign="top">Very emotional shot, Barbara.  I think the composition hurt your score, though it was clear even during voting there was a story to be learned here.  Putting the man and the box in opposite corners might have helped, along with getting the box a little away from the edge.  That would make the space work as a separation, showing that the ashes have left the box and are now flying free in the world.  As it is, the image feels unbalanced, with a whole lot of space on the left not really contributing to the story.<br/> <br/>Edited to thank you for sharing your father''s story.  This is good example of an image that''s much more powerful for knowing the background.  DPC''s competition format doesn''t provide the opportunity for appreciating the moment as much as the photo all by itself.<br/><br/><i>Message edited by author 2007-08-29 21:39:04.</i></td>', 'Very emotional shot, Barbara.  I think the composition hurt your score, though it was clear even during voting there was a story to be learned here.  Putting the man and the box in opposite corners might have helped, along with getting the box a little away from the edge.  That would make the space work as a separation, showing that the ashes have left the box and are now flying free in the world.  As it is, the image feels unbalanced, with a whole lot of space on the left not really contributing to the story. Edited to thank you for sharing your father''s story.  This is good example of an image that''s much more powerful for knowing the background.  DPC''s competition format doesn''t provide the opportunity for appreciating the moment as much as the photo all by itself.', '2007-08-29 02:21:45.000000', '2007-08-29 22:39:04.000000', 0),
(4037283, 575307, 68504, '<td valign="top">Delightful, as should sacred be.</td>', 'Delightful, as should sacred be.', '2007-08-29 02:22:37.000000', NULL, 0),
(4037285, 573825, 60862, '<td valign="top">Julianne, I voted this a 6 as a nice, pretty, peaceful scene with interesting colors and shapes.  I encourage you to explore perspective correction tools if you have them available.  In particular either skew or perspective could have straightened out the verticals on the left side.</td>', 'Julianne, I voted this a 6 as a nice, pretty, peaceful scene with interesting colors and shapes.  I encourage you to explore perspective correction tools if you have them available.  In particular either skew or perspective could have straightened out the verticals on the left side.', '2007-08-29 02:23:11.000000', NULL, 0),
(4037293, 573673, 68504, '<td valign="top">Wonderful portrait.  You have portrayed a fine spirit.</td>', 'Wonderful portrait.  You have portrayed a fine spirit.', '2007-08-29 02:25:15.000000', NULL, 0),
(4037299, 573511, 30861, '<td valign="top">Hey, congrats to you! Isn''t it exciting? Lovely, ethereal image.</td>', 'Hey, congrats to you! Isn''t it exciting? Lovely, ethereal image.', '2007-08-29 02:27:33.000000', NULL, 0),
(4037304, 573842, 30861, '<td valign="top">Very nicely done, so much sense of gravitas and place. A welcome change from the spectacular that so often dominates our ribbons.</td>', 'Very nicely done, so much sense of gravitas and place. A welcome change from the spectacular that so often dominates our ribbons.', '2007-08-29 02:28:48.000000', NULL, 0),
(4037309, 575404, 68504, '<td valign="top">Truly fascinating.</td>', 'Truly fascinating.', '2007-08-29 02:30:15.000000', NULL, 0),
(4037310, 574764, 16241, '<td valign="top">dramatic, congrats on your ribbon.</td>', 'dramatic, congrats on your ribbon.', '2007-08-29 02:30:16.000000', NULL, 0),
(4037312, 575540, 30861, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by levyj413:</b></div><hr/><i> A very pretty scene, but it''s seriously degraded by all the dust on either the lens or the sensor.  I suggest learning how to clean your sensor and lens and also how to use the clone tool to remove stuff like that. </i></td></tr></table> <br/> <br/>Levy, I''m pretty sure those are BIRDS. I magnified the image, and a lot of the "spots are birds for sure :-)<br/> <br/>Thomas, fine shot, "damned beach"!</td>', 'Originally posted by levyj413: A very pretty scene, but it''s seriously degraded by all the dust on either the lens or the sensor.  I suggest learning how to clean your sensor and lens and also how to use the clone tool to remove stuff like that.   Levy, I''m pretty sure those are BIRDS. I magnified the image, and a lot of the "spots are birds for sure :-) Thomas, fine shot, "damned beach"!', '2007-08-29 02:30:28.000000', NULL, 0),
(4037320, 573994, 68504, '<td valign="top">Enigmatic.  Style worthy of content.</td>', 'Enigmatic.  Style worthy of content.', '2007-08-29 02:33:35.000000', NULL, 0),
(4037337, 575540, 60862, '<td valign="top">Thomas, I think that, blown up to large format and hanging on a gallery wall, the birds would be a delightful surprise as you walked closer.<br/> <br/>But at this small image size, they''re just distracting spots.  And Bear, I was hardly the one to note that. :P<br/> <br/>Anyway, it really is a beautiful shot, so congrats!</td>', 'Thomas, I think that, blown up to large format and hanging on a gallery wall, the birds would be a delightful surprise as you walked closer. But at this small image size, they''re just distracting spots.  And Bear, I was hardly the one to note that. :P Anyway, it really is a beautiful shot, so congrats!', '2007-08-29 02:45:32.000000', NULL, 0),
