(4215993, 575212, 71105, '<td valign="top">Hey Sean, I haven''t "checked on you" in a while on this thing, and hadn''t seen this entry yet.  Great shot!  I see you''re using photoshop more and more... awesome!  I added a few local shots to my portfolio recently if you want to check them out.  Stay in touch!  Chris.  PS- this is where?  Never heard of it... haha.</td>', 'Hey Sean, I haven''t "checked on you" in a while on this thing, and hadn''t seen this entry yet.  Great shot!  I see you''re using photoshop more and more... awesome!  I added a few local shots to my portfolio recently if you want to check them out.  Stay in touch!  Chris.  PS- this is where?  Never heard of it... haha.', '2007-11-02 14:40:51.000000', NULL, 0),
(4251157, 574604, 47906, '<td valign="top">Excellent detail and shaprness in this portrait. Very crisp and detailed. I didnt vote in this challenge but would have been a 9 from me. Great shot. Congrats on a 6th place finish.</td>', 'Excellent detail and shaprness in this portrait. Very crisp and detailed. I didnt vote in this challenge but would have been a 9 from me. Great shot. Congrats on a 6th place finish.', '2007-11-16 07:57:05.000000', NULL, 0);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4468176, 575067, 48471, '<td valign="top">So, who''s the guy on the photo? It can''t be a church figure, it has a beard. It looks more like the European scientists from the XIX century.</td>', 'So, who''s the guy on the photo? It can''t be a church figure, it has a beard. It looks more like the European scientists from the XIX century.', '2008-02-07 11:48:12.000000', NULL, 0),
(4542479, 575002, 7756, '<td valign="top">Amazing shot. 22 mins thats great!</td>', 'Amazing shot. 22 mins thats great!', '2008-03-06 03:20:41.000000', NULL, 0),
(4592947, 574604, 68586, '<td valign="top">''Harris Hawk'' - I thought he was an Private Eye from the old ''B'' Movies ?<br/> <br/>I still remember fondly the series of films he did when he was sponsored by the Coffee Giants - classics Westerns like ''Harris Hawk and the Mocha Indians'', or his part in the famous War film - ''Von Ryans Expresso''  :- ) <br/> <br/>As for this Bird that''s clearly blocking the picture - very nice crisp shot.</td>', '''Harris Hawk'' - I thought he was an Private Eye from the old ''B'' Movies ? I still remember fondly the series of films he did when he was sponsored by the Coffee Giants - classics Westerns like ''Harris Hawk and the Mocha Indians'', or his part in the famous War film - ''Von Ryans Expresso''  :- )  As for this Bird that''s clearly blocking the picture - very nice crisp shot.', '2008-03-28 05:00:48.000000', NULL, 0),
(4608318, 575375, 91804, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by ChicPhotog:</b></div><hr/><i> Kind of a boring shot to me, maybe if you couldv''e gotten more of the statue in the shot it wouldve worked better </i></td></tr></table> <br/> <br/>If this seems boring and poorly composed to you, I would assume that you have not been there to see the real thing.  True, it would be great to see the whole thing, however...It''s behind glass, the glass is in sections (so if you move the wrong direction you will have a window joint through your picture), there are a million people packed in there like sardines trying to get a look at it simultaneously, no flash, no tripod, no monopod.  I''m amazed it''s not a giant blur with someone''s head in the frame.</td>', 'Originally posted by ChicPhotog: Kind of a boring shot to me, maybe if you couldv''e gotten more of the statue in the shot it wouldve worked better   If this seems boring and poorly composed to you, I would assume that you have not been there to see the real thing.  True, it would be great to see the whole thing, however...It''s behind glass, the glass is in sections (so if you move the wrong direction you will have a window joint through your picture), there are a million people packed in there like sardines trying to get a look at it simultaneously, no flash, no tripod, no monopod.  I''m amazed it''s not a giant blur with someone''s head in the frame.', '2008-04-02 19:14:42.000000', NULL, 0),
(4660860, 575212, 74979, '<td valign="top">beautiful!  what a great finish too!!<br/></td>', 'beautiful!  what a great finish too!!', '2008-04-27 10:23:11.000000', NULL, 0),
